import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import type { McpServer } from '@modelcontextprotocol/server';
import type { ChaincodeApi } from './scan.js';

/**
 * Expose chaincode API descriptions as MCP resources so the model can look up
 * contract/method names instead of guessing. The file is generated by
 * `mcp-server-hyperledger-fabric scan`; each chaincode becomes a resource at
 * fabric://chaincode/<name>. Files are re-read on every access, so edits
 * apply without a server restart.
 */

/** Resolve a file or directory path to the list of chaincode-api JSON files. */
export function resolveApiFiles(apiPath: string): string[] {
  const st = statSync(apiPath);
  if (st.isDirectory()) {
    return readdirSync(apiPath)
      .filter((f) => f.endsWith('.json'))
      .sort()
      .map((f) => join(apiPath, f));
  }
  return [apiPath];
}

/** Parse one API file; malformed files are skipped, not fatal. */
function parseApiFile(file: string): ChaincodeApi | undefined {
  try {
    const api = JSON.parse(readFileSync(file, 'utf8')) as ChaincodeApi;
    if (typeof api.chaincode === 'string' && Array.isArray(api.contracts)) return api;
  } catch {
    // skip malformed file — one bad JSON must not kill the server
  }
  return undefined;
}

/** Load all chaincode API descriptions from a file or directory. */
export function loadChaincodeApis(apiPath: string): ChaincodeApi[] {
  return resolveApiFiles(apiPath)
    .map(parseApiFile)
    .filter((a): a is ChaincodeApi => a !== undefined);
}

/** Register one MCP resource per chaincode in the API file(s). */
export function registerChaincodeResources(server: McpServer, apiPath: string): void {
  const seen = new Set<string>();
  for (const file of resolveApiFiles(apiPath)) {
    const api = parseApiFile(file);
    if (!api || seen.has(api.chaincode)) continue; // skip malformed + duplicate names
    seen.add(api.chaincode);
    server.registerResource(
      `${api.chaincode} chaincode API`,
      `fabric://chaincode/${api.chaincode}`,
      { title: `${api.chaincode} chaincode API`, mimeType: 'application/json' },
      async (uri: URL) => {
        const fresh = parseApiFile(file) ?? api;
        return {
          contents: [
            {
              uri: uri.toString(),
              mimeType: 'application/json',
              text: JSON.stringify(fresh, null, 2),
            },
          ],
        };
      },
    );
  }
}
